"""Camera source declarations for the Source Bus control plane.

Camera media stays outside gRPC. These models describe and negotiate the
control-plane metadata for the media protocol Loop should consume.
"""

from __future__ import annotations

from collections.abc import Callable
from enum import Enum
from urllib.parse import urlsplit

from pydantic import BaseModel, ConfigDict, Field, field_validator, model_validator

from loop_sdk.source.domain.source_kind import SourceKind


class RtspTransport(str, Enum):
    """Transport mode for an advertised RTSP endpoint."""

    TCP = "tcp"
    UDP = "udp"


class ZmqMessageMode(str, Enum):
    """Message framing mode for an advertised ZMQ camera endpoint."""

    SINGLE_FRAME = "single_frame"


class CameraFrameEncoding(str, Enum):
    """Wire encoding carried by a camera media endpoint."""

    JPEG = "jpeg"


class CameraPixelFormat(str, Enum):
    """Camera media formats supported by this SDK."""

    MJPEG = "mjpeg"


class CameraResolution(BaseModel):
    """Pixel dimensions for a camera setting."""

    model_config = ConfigDict(frozen=True)

    width: int = Field(gt=0)
    height: int = Field(gt=0)


class CameraSetting(BaseModel):
    """One selectable camera capture mode."""

    model_config = ConfigDict(frozen=True)

    resolution: CameraResolution
    fps: float = Field(gt=0)
    pixel_format: CameraPixelFormat = CameraPixelFormat.MJPEG
    horizontal_flip: bool = False
    vertical_flip: bool = False


class RtspCameraProtocol(BaseModel):
    """Reachable RTSP endpoint Loop should pull for a camera source."""

    model_config = ConfigDict(frozen=True)

    uri: str
    transport: RtspTransport = RtspTransport.TCP

    @field_validator("uri")
    @classmethod
    def _validate_rtsp_uri(cls, value: str) -> str:
        parsed = urlsplit(value)
        if parsed.scheme not in {"rtsp", "rtsps"} or not parsed.netloc:
            raise ValueError("camera RTSP endpoint uri must be an rtsp:// or rtsps:// URI with a host")
        return value


RtspCameraEndpoint = RtspCameraProtocol


class ZmqCameraProtocol(BaseModel):
    """Reachable ZMQ endpoint Loop should subscribe to for a camera source."""

    model_config = ConfigDict(frozen=True)

    uri: str
    message_mode: ZmqMessageMode = ZmqMessageMode.SINGLE_FRAME
    frame_encoding: CameraFrameEncoding = CameraFrameEncoding.JPEG

    @field_validator("uri")
    @classmethod
    def _validate_zmq_uri(cls, value: str) -> str:
        parsed = urlsplit(value)
        if (
            parsed.scheme != "tcp"
            or not parsed.hostname
            or parsed.port is None
            or parsed.path
            or parsed.query
            or parsed.fragment
        ):
            raise ValueError("camera ZMQ endpoint uri must be a tcp://host:port URI")
        return value


class CameraStreamSchema(BaseModel):
    """A camera source whose media is pulled by Loop from one advertised protocol."""

    model_config = ConfigDict(frozen=True)

    source_key: str
    name: str = ""
    rtsp: RtspCameraProtocol | None = None
    zmq: ZmqCameraProtocol | None = None
    available_settings: tuple[CameraSetting, ...] = ()

    @model_validator(mode="after")
    def _validate_one_protocol(self) -> CameraStreamSchema:
        if (self.rtsp is None) == (self.zmq is None):
            raise ValueError("camera stream must set exactly one protocol: rtsp or zmq")
        return self

    @property
    def kind(self) -> SourceKind:
        return SourceKind.CAMERA


class CameraOpenResult(BaseModel):
    """Result of applying a camera Open command.

    A protocol override is optional: omit it when the scan-time endpoint remains
    valid.
    """

    model_config = ConfigDict(frozen=True)

    applied_setting: CameraSetting | None = None
    rtsp: RtspCameraProtocol | None = None
    zmq: ZmqCameraProtocol | None = None

    @model_validator(mode="after")
    def _validate_protocol_override(self) -> CameraOpenResult:
        if self.rtsp is not None and self.zmq is not None:
            raise ValueError("camera open result may set at most one protocol: rtsp or zmq")
        return self


OnCameraOpen = Callable[[CameraSetting | None], CameraOpenResult | None]
